import{_ as r,C as t,o,c as n,a2 as e,E as s}from"./chunks/framework.CDpkVv68.js";const f=JSON.parse('{"title":"Magery: visión general","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/magic/overview.md","filePath":"es/guide/magic/overview.md"}'),d={name:"es/guide/magic/overview.md"};function c(l,a,p,h,u,m){const i=t("WikiVisual");return o(),n("div",null,[a[0]||(a[0]=e('<h1 id="magery-overview" tabindex="-1">Magery: visión general <a class="header-anchor" href="#magery-overview" aria-label="Enlace permanente a &quot;Magery: visión general&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Disponibilidad no confirmada.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Magery apoya la ejecución; los <a href="/Syrolands-Public/es/guide/magic/learning-spells.html">Core Patterns</a> (estructuras base de los hechizos) aportan conocimiento aprendido.</li><li>La práctica y la preparación determinan qué hechizos puedes usar con facilidad.</li><li>El descubrimiento continúa más allá del dominio de la <a href="/Syrolands-Public/es/guide/characters/skills.html">habilidad</a>.</li></ul><p><span id="at-a-glance"></span><span id="progression-and-trade-offs"></span></p>',5)),s(i,{"asset-id":"hero-magic"}),a[1]||(a[1]=e('<h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elemento</th><th>Qué significa para el jugador</th></tr></thead><tbody><tr><td>Core Pattern</td><td>La identidad aprendida de un hechizo, con variantes compatibles por descubrir.</td></tr><tr><td>Magery</td><td>Tu capacidad para ejecutar un hechizo, no su conocimiento automático.</td></tr><tr><td><a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a> (fluidez práctica)</td><td>La práctica con un patrón concreto.</td></tr><tr><td><a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Active Memory</a> (memoria activa)</td><td>Acceso preparado al lanzamiento normal, nunca éxito instantáneo.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Orientación de Syrolands</th></tr></thead><tbody><tr><td>Magery ya implica libros de hechizos, habilidad, maná y reactivos.</td><td>Se conservan recursos de lanzamiento significativos, separando patrones aprendidos, práctica y preparación.</td></tr><tr><td>Los hechizos de un libro pueden seleccionarse para lanzarlos, sujetos a sus requisitos.</td><td>Active Memory determina el acceso preparado; los patrones conocidos sin preparar pueden requerir tiempo de consulta.</td></tr><tr><td>Magery tiene un catálogo definido de hechizos.</td><td>Descubre Core Patterns y modificadores aprendidos compatibles a través del mundo.</td></tr></tbody></table><p>Las reglas de UO varían según la época y el shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/magery/" target="_blank" rel="noreferrer">UO oficial: Magery y Meditation</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Dos magos con igual habilidad pueden conocer patrones diferentes. Un especialista bien preparado puede entrar en un encuentro con un hechizo útil listo, mientras otro necesita tiempo para consultar una referencia.</p><h2 id="progression-trade-offs" tabindex="-1">Progresión y contrapartidas <a class="header-anchor" href="#progression-trade-offs" aria-label="Enlace permanente a &quot;Progresión y contrapartidas&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/glossary.html#mastery">Mastery</a> (dominio) amplio significa especialización en una disciplina o afinidad; es distinto de Familiarity por patrón. Poder intentar un hechizo, ejecutarlo con éxito y resistir interrupciones siguen siendo cuestiones diferentes.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/magic/learning-spells.html">Aprender hechizos</a> · <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria y Familiarity</a> · <a href="/Syrolands-Public/es/guide/magic/variants-and-glyphs.html">Variantes de hechizos</a> · <a href="/Syrolands-Public/es/guide/magic/meditation-and-concentration.html">Meditation</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p>Consulta la especificación de diseño: <a href="/Syrolands-Public/es/game-design/magic.html">Magery: visión general</a>.</p>',13))])}const y=r(d,[["render",c]]);export{f as __pageData,y as default};
